xql_query:
// ============================================================
// Rule: MS_Suspicious High-Privilege App Role Assignment
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with MS_Suspicious High-Privilege App Role Assignment.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1098 - Account Manipulation

// Desativa case sensitive, para facilitar filtros de texto
config case_sensitive = false 

// Define dataset: logs de auditoria da nuvem (Azure AD)
| dataset = cloud_audit_logs
// Filtra somente eventos do Azure AD relacionados a atribuição de roles em Service Principals
| filter (log_name = """azure_ad_audit_logs""") and operation_name_orig in ("Add app role assignment to service principal") 

// Extrai campo JSON com propriedades modificadas (modifiedProperties)
| alter mod_props = json_extract(raw_log, "$.properties.targetResources.0.modifiedProperties")

// Corrige problemas de escape de caracteres no JSON
| alter old_str = to_string("""\\""") 
| alter new_str = to_string("""\\\\\\""") 
| alter extract = replace(mod_props , old_str, new_str) 

// Converte array para formato tratável
| alter extract = extract -> [] 

// Reconstrói JSON em formato chave:valor (displayName : newValue)
| alter extract = concat("{",arraystring(arraymap(extract, concat("\"","@element"->displayName,"\":\"","@element"->newValue,"\"")),","),"}") 

// Remove pontos nos nomes das chaves para evitar erro em parsing
| alter Perms = replex(extract,"\.","_") 

// Extrai nome do Service Principal
| alter ServicePrincipal_DisplayName = json_extract_scalar(Perms, "$.ServicePrincipal_DisplayName") 

// Extrai as permissões (AppRole_Value)
| alter permissions = Perms -> AppRole_Value 

// Remove aspas extras das permissões
| alter permissions = replex(permissions, "\"","") 

// Foco em permissões críticas: privilegiam acesso a diretório, arquivos, e-mails, grupos etc.
| filter permissions in ("Directory_ReadWrite_All","User_ReadWrite_All","Application_ReadWrite_All","RoleManagement_ReadWrite_Directory","Files_ReadWrite_All","Mail_ReadWrite","Group_ReadWrite_All","Calendars_ReadWrite") 

// Captura o user agent utilizado (útil para identificar automação ou anomalias)
| alter user_agent = json_extract_scalar(raw_log, "$.properties.additionalDetails.0.value") 

// Seleciona os campos relevantes para investigação
| fields _time, operation_name_orig, identity_name, referenced_resource_name as ServicePrincipalName, ServicePrincipal_DisplayName, permissions, user_agent, caller_ip, caller_ip_asn, caller_ip_asn_org, caller_ip_geolocation, raw_log, operation_status 

// Remove duplicados no mesmo timestamp para evitar ruído
| dedup _time, identity_name, ServicePrincipal_DisplayName, permissions
